use arrow_array::{Array, Int64Array, cast::AsArray, types::Decimal128Type};
use arrow_cast::cast;
use arrow_schema::DataType;
use std::{
    hint::black_box,
    sync::{Arc, Barrier},
    time::Instant,
};

fn main() {
    let args = std::env::args().collect::<Vec<_>>();
    let threads: usize = args[1].parse().unwrap();
    let retain = match args[2].as_str() {
        "stream" => false,
        "retain" => true,
        _ => panic!("mode"),
    };
    let barrier = Arc::new(Barrier::new(threads));
    let jobs = (0..threads)
        .map(|_| {
            let barrier = barrier.clone();
            std::thread::spawn(move || {
                let input = Int64Array::from_iter_values((0..8192).map(|i| i as i64 - 4096));
                let target = DataType::Decimal128(38, 6);
                let check = cast(&input, &target).unwrap();
                assert!(
                    check
                        .as_primitive::<Decimal128Type>()
                        .values()
                        .iter()
                        .zip(input.values())
                        .all(|(actual, expected)| *actual == i128::from(*expected) * 1_000_000)
                );
                drop(check);
                let mut samples = Vec::new();
                for round in 0..11 {
                    barrier.wait();
                    let start = Instant::now();
                    let mut held = Vec::with_capacity(if retain { 128 } else { 0 });
                    for _ in 0..128 {
                        let output = cast(black_box(&input), black_box(&target)).unwrap();
                        assert_eq!(output.len(), 8192);
                        if retain {
                            held.push(output);
                        } else {
                            black_box(output);
                        }
                    }
                    drop(black_box(held));
                    let ms = start.elapsed().as_secs_f64() * 1000.0;
                    if round >= 2 {
                        samples.push(ms);
                    }
                    barrier.wait();
                }
                samples
            })
        })
        .collect::<Vec<_>>();
    let samples: Vec<_> = jobs.into_iter().map(|job| job.join().unwrap()).collect();
    println!(
        "{{\"threads\":{threads},\"mode\":\"{}\",\"rows_per_thread_per_sample\":1048576,\"samples_ms_by_thread\":{:?}}}",
        args[2], samples
    );
}

